<script setup lang="ts">
import { isUnavailable, type ControlState } from "./control-state";
withDefaults(defineProps<{ modelValue?: string; label: string; options: readonly { value: string; label: string }[]; disabled?: boolean; state?: ControlState }>(), { modelValue: "", state: "default" });
defineEmits<{ "update:modelValue": [value: string] }>();
</script>
<template><label class="field"><span>{{ label }}</span><select :value="modelValue" :disabled="isUnavailable(state, disabled)" :data-state="state" :aria-busy="state === 'loading' || undefined" :aria-invalid="state === 'error'" @change="$emit('update:modelValue', ($event.target as HTMLSelectElement).value)"><option v-for="option in options" :key="option.value" :value="option.value">{{ option.label }}</option></select></label></template>
<style scoped>.field { display:grid; gap:var(--space-1); color:var(--ctp-subtext0); font-size:var(--font-small); }.field select { min-height:var(--button-height); padding:0 var(--space-2); color:var(--ctp-text); background:var(--ctp-surface0); border:1px solid var(--ctp-surface1); border-radius:var(--radius-control); }.field select:hover, .field select[data-state="hover"] { background:var(--ctp-surface1); }.field select[data-state="focus"] { outline:2px solid var(--ctp-mauve); outline-offset:2px; }.field select[data-state="active"] { border-color:var(--ctp-surface2); }.field select[data-state="error"] { border-color:var(--ctp-red); }.field select:disabled { color:var(--ctp-overlay0); }</style>
